base = pathlib.Path("data/corpus")
base.mkdir(parents=True, exist_ok=True)
for c in corpus:
    (base / f"{c['id']}.json").write_text(json.dumps(c, ensure_ascii=True, indent=2), encoding="utf-8")
print(f"{len(corpus)} fontes escritas em data/corpus/")